  const t = s.trim();
  if (t.length === 0) return 0;
  return t.split(/\s+/).length;
}

module.exports = { trim, capitalize, reverse, countWords };

test('reverse', () => {
  assert.strictEqual(reverse('abc'), 'cba');
  assert.strictEqual(reverse(''), '');
  assert.strictEqual(reverse('ab🙂'), '🙂ba');
});

test('countWords', () => {
  assert.strictEqual(countWords('a b c'), 3);
  assert.strictEqual(countWords('  a   b  '), 2);
  assert.strictEqual(countWords('a\nb\tc'), 3);
  assert.strictEqual(countWords(''), 0);
  assert.strictEqual(countWords('   '), 0);
});

